from typing import Any, Optional

# Record comes in as a raw dict from ingested JSON
def normalize_amount(raw: dict[str, Any]) -> Optional[float]:
    """Return the amount as a float, or None if it is missing/blank."""
    value: str | float | None = raw.get("amount")
    if value is None or value == "":
        return None
    return float(value)

def clean_rows(rows: list[dict[str, Any]]) -> list[dict[str, float]]:
    cleaned: list[dict[str, float]] = []
    for row in rows:
        amount = normalize_amount(row)
        if amount is not None and amount > 0:
            cleaned.append({"order_id": row["order_id"], "amount": amount})
    return cleaned

sample = [
    {"order_id": "A1", "amount": "19.99"},
    {"order_id": "A2", "amount": ""},
    {"order_id": "A3", "amount": 5},
]
print(clean_rows(sample))

from typing import Protocol, Callable, TypeVar

class RowSource(Protocol):
    def read_rows(self) -> list[dict[str, str]]:
        ...

class CsvSource:
    def __init__(self, rows: list[dict[str, str]]) -> None:
        self._rows = rows
    def read_rows(self) -> list[dict[str, str]]:
        return self._rows

# Accepts ANY object with a read_rows() method (structural typing)
def count_rows(source: RowSource) -> int:
    return len(source.read_rows())

# Callable: a transform that maps one dict to another
def apply_transform(
    rows: list[dict[str, str]], fn: Callable[[dict[str, str]], dict[str, str]]
) -> list[dict[str, str]]:
    return [fn(r) for r in rows]

# Generic: preserves the element type of whatever list is passed
T = TypeVar("T")
def first(items: list[T]) -> T:
    return items[0]

src = CsvSource([{"id": "1"}, {"id": "2"}])
print(count_rows(src))
print(apply_transform(src.read_rows(), lambda r: {"id": r["id"].zfill(3)}))
print(first([10, 20, 30]))
